def place_order():
    """Simulate a customer order system using for and while loops."""

    # Initialize order items and quantities
    order_items = {
        "pizza": 1,
        "burgers": 2,
        "sandwiches": 3
    }

    # Display the available items and quantities
    print("Available items and quantities:")
    for item, quantity in order_items.items():
        print(f"{item}: {quantity}")

    while True:
        item_name = input("\nEnter the item you want to order (or type 'done' to finish): ").lower()

        if item_name == "done":
            break

        if item_name not in order_items:
            print(f"Sorry, we don't have {item_name} in stock. Please try again.")
            continue

        quantity = int(input(f"Enter the quantity of {item_name}: "))

        if quantity <= 0:
            print("Please enter a positive quantity. Try again.")
            continue

        order_items[item_name] -= quantity

        if order_items[item_name] == 0:
            print(f"Sorry, we're out of {item_name}. Please try again later.")

    # Display the order details
    print("\nOrder placed successfully!")
    for item, quantity in order_items.items():
        print(f"{item}: {quantity} items")


if __name__ == "__main__":
    place_order()
```

This program will allow the user to place orders for pizza, burgers, and sandwiches until they type 'done' to finish. The order details will be displayed once the order is placed successfully.
